const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),root=document.getElementById('bundles'),dialog=document.getElementById('editor'),candidates=document.getElementById('candidates'),current=document.getElementById('current'),state=document.getElementById('state');let active=0;
const image=(url,label,checked=false)=>`<label><input type="checkbox" value="${esc(url)}" ${checked?'checked':''}><img src="${esc(url)}" alt="${esc(label)}"><small>${esc(label)}</small></label>`;
async function load(){const response=await fetch('/api/admin/bundle-preview-audit',{cache:'no-store'}),data=await response.json().catch(()=>({}));root.innerHTML=response.ok&&data.items.length?data.items.map(item=>`<article class="bundle"><div><b>${esc(item.title)}</b><small> · ID ${item.id} · ${item.member_count} ตะกร้า · แก้รูป ${item.revision_count} ครั้ง</small></div><button data-id="${item.id}">ตรวจรูป</button></article>`).join(''):'<p>ยังไม่มีตะกร้ารวม</p>';root.querySelectorAll('button').forEach(button=>button.onclick=()=>open(button.dataset.id))}
async function open(id){active=id;state.textContent='กำลังโหลด…';dialog.showModal();const response=await fetch(`/api/admin/bundle-preview-audit/${id}`,{cache:'no-store'}),data=await response.json();document.getElementById('title').textContent=data.bundle.title;current.className='gallery current';current.innerHTML=data.bundle.preview_urls.map((url,index)=>image(url,`รูปเดิม ${index+1}`)).join('');const seen=new Set();candidates.className='gallery';candidates.innerHTML=data.members.flatMap(member=>[member.cover_url,...member.preview_urls].map(url=>({url,label:member.title}))).filter(item=>item.url&&!seen.has(item.url)&&seen.add(item.url)).map(item=>image(item.url,item.label,data.bundle.preview_urls.includes(item.url))).join('');state.textContent=''}
document.getElementById('save').onclick=async()=>{const button=document.getElementById('save'),preview_urls=[...candidates.querySelectorAll('input:checked')].map(input=>input.value);button.disabled=true;state.textContent='กำลังบันทึก Snapshot และเปลี่ยนรูป…';const response=await fetch(`/api/admin/bundle-preview-audit/${active}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({preview_urls})}),data=await response.json().catch(()=>({}));button.disabled=false;if(!response.ok){state.className='error';state.textContent=data.error||'บันทึกไม่สำเร็จ';return}state.className='';state.textContent='เปลี่ยนเฉพาะรูปใน Product ID เดิมแล้ว';await load();setTimeout(()=>dialog.close(),500)};load();
